import * as React from "react";
import Layout from "../components/layout";
import { graphql, PageProps } from "gatsby";
import data from "../data/data.json";
import { UserProfile } from "../interfaces";
import { useTranslation } from "gatsby-plugin-react-i18next";
import images from "../images";
import ButtonComponent from "../components/buttons";

const userData: UserProfile = data;

const IndexPage: React.FC<PageProps> = () => {
  const { t } = useTranslation();

  const videoRefs = React.useRef<{ [key: string]: HTMLVideoElement | null }>({});
  const hoverTimeouts = React.useRef<{ [key: string]: number | undefined }>({});
  const [playing, setPlaying] = React.useState<{ [key: string]: boolean }>({});

  const videoKey = "homePage"; 

  const handleMouseEnter = () => {
    clearTimeout(hoverTimeouts.current[videoKey]);
    setPlaying((prev) => ({ ...prev, [`${videoKey}-hover`]: true }));
  };

  const handleMouseLeave = () => {
    if (playing[videoKey]) {
      const timeout = window.setTimeout(() => {
        setPlaying((prev) => ({ ...prev, [`${videoKey}-hover`]: false }));
      }, 800);
      hoverTimeouts.current[videoKey] = timeout;
    } else {
      setPlaying((prev) => ({ ...prev, [`${videoKey}-hover`]: false }));
    }
  };

  const handleVideoToggle = (videoKey: string) => {
    const video = videoRefs.current[videoKey];
    if (!video) return;

    if (video.paused || video.ended) {
      video.play();
      setPlaying((prev) => ({ ...prev, [videoKey]: true }));
    } else {
      video.pause();
      video.currentTime = 0;
      setPlaying((prev) => ({ ...prev, [videoKey]: false }));
    }
  };
  return (
    <Layout
      data={userData}
      iconAndTextColor="Tofu"
      footerLogoFill="fill-Trooper"
      footerColorText="text-Trooper"
      bgColorPage="DarkSea"
      bgImage={images.homeVideo.src}
      footerBackground="linear-gradient(to top, rgba(32,47,47,1) 0%,rgba(32,47,47,0) 100%)"
      paddingBottomClassBackground="pb-[150%] sm:pb-[91.67%]"
    >
      <section className={styles.container}>
        <h1
          className={styles.title}
          dangerouslySetInnerHTML={{ __html: t("home.title") ?? "" }}
        />

        <section className="flex flex-col sm:flex-row text-Tofu justify-between w-full mt-10">
          <article className="w-full sm:w-[600px]">
            <p className="body-2 sm:body-1">{t("home.paragraph1")}</p>
            <p className="body-2 sm:body-1 mt-12">{t("home.paragraph2")}</p>
          </article>

          <aside className="w-full sm:w-[380px] flex flex-col gap-8 mt-8 sm:mt-2">
            {(Array.isArray(t("home.details", { returnObjects: true }))
              ? (t("home.details", { returnObjects: true }) as any[])
              : []
            ).map((item, index) => (
              <div key={index} className="flex flex-col gap-4 items-start">
                <img
                  src={`./${item.icon}`}
                  alt={item.title}
                  className="h-10 mb-4"
                />
                <h2 className="head-7 sm:head-6">{item.title}</h2>
                <p className="body-4 sm:body-3">{item.text}</p>
              </div>
            ))}
          </aside>
        </section>

        <section className="flex flex-col sm:flex-row text-Tofu justify-between w-full my-10 sm:my-24">
          <article className="relative w-[calc(100%+40px)] sm:w-[1050px] -ml-[20px] sm:-ml-0">
            <div
              className="relative group"
              onMouseEnter={handleMouseEnter}
              onMouseLeave={handleMouseLeave}
            >
              <video
                ref={(el) => { videoRefs.current[videoKey] = el; }}
                poster={images.image1.src}
                className="w-full pr-0 sm:pr-8"
                preload="metadata"
              >
                <source src={images.homePage.src} type="video/mp4" />
                <track kind="captions" srcLang="en" label="English" default />
                Tu navegador no soporta video.
              </video>

              <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
                <button
                  onClick={() => handleVideoToggle(videoKey)}
                  aria-label={playing[videoKey] ? "Pause video" : "Play video"}
                  className={`pointer-events-auto bg-black/60 text-white p-4 rounded-full z-10 hover:bg-black/80 transition duration-300 ${
                    playing[`${videoKey}-hover`] || !playing[videoKey]
                      ? "opacity-100"
                      : "opacity-0"
                  }`}
                >
                  {playing[videoKey] ? (
                    <svg
                      xmlns="http://www.w3.org/2000/svg"
                      className="w-8 h-8"
                      fill="currentColor"
                      viewBox="0 0 24 24"
                      aria-hidden="true"
                    >
                      <path d="M6 4h4v16H6zm8 0h4v16h-4z" />
                    </svg>
                  ) : (
                    <svg
                      xmlns="http://www.w3.org/2000/svg"
                      className="w-8 h-8"
                      fill="currentColor"
                      viewBox="0 0 24 24"
                      aria-hidden="true"
                    >
                      <path d="M8 5v14l11-7z" />
                    </svg>
                  )}
                </button>
              </div>
            </div>
          </article>

          <aside className="w-full sm:w-[380px] flex flex-col gap-8 mt-8 sm:mt-2 mb-24 sm:mb-0">
            <h4
              className="head-3"
              dangerouslySetInnerHTML={{ __html: t("home.cta.title") ?? "" }}
            ></h4>
            <p className="body-3">{t("home.cta.text")}</p>
            <ButtonComponent isDisabled={false} />
          </aside>
        </section>
      </section>
    </Layout>
  );
};

export default IndexPage;

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;

const styles = {
  container: "w-full px-5 sm:px-16 mt-[300px] sm:mt-[486px]",
  section: "flex h-96 bg-primary my-8 w-full border border-primary rounded-lg shadow-md",
  title: "head-3 sm:head-1 text-Tofu",
};
import SEO from "../components/seo";
import type { HeadProps } from "gatsby";
import translations from "../locales/en/index.json";
const _seoData: UserProfile = data as unknown as UserProfile;
export const Head = ({ location, pageContext }: HeadProps<Record<string, unknown>, { language?: string; i18n?: { originalPath?: string } }>) => (
  <SEO
    data={_seoData}
    title={translations.seo.home.title}
    description={translations.seo.home.description}
    language={pageContext.language ?? "en"}
    languages={["en"]}
    defaultLanguage="en"
    originalPath={pageContext.i18n?.originalPath ?? location.pathname}
    schemaType="ProfessionalService"
    includeLocalBusinessDetails
    pageSchemaType="WebPage"
    pageSchemaName="Reef Cleaning Company — Home"
  />
);
